package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();CarDetail c=new CarDetail("OWN-01","AB 123 Polo","White","Volkswagen");s.persist(new CarOwner(1,"Meenakshi",c));t.commit();System.out.println("One-to-one owner/car persisted.");}HibernateUtil.getSessionFactory().close();}}